if (n == 0) return 1;
if (n < 0) return 1 / power(x, -n);
std::int64_t result = 1;
std::int64_t base = x;
std::int64_t exp = std::abs(std::static_cast<std::int64_t>(n));
while (exp > 0) {
    if (exp % 2 == 1) {
        result *= base;
    }
    base *= base;
    exp /= 2;
}
return static_cast<int>(result);
// END_CODE

